class Solution {
public:
    vector<string> topKFrequent(vector<string>& words, int k) {
        map<string, int> cnt;
        for (auto& w : words) cnt[w]++;
        vector<string> order;
        for (auto& [w, c] : cnt) order.push_back(w);
        sort(order.begin(), order.end(), [&](const string& a, const string& b) {
            return cnt[a] != cnt[b] ? cnt[a] > cnt[b] : a < b;
        });
        order.resize(k);
        return order;
    }
};
